-- every business still exists, is not merged away and has the name Tom saw
DO $$ DECLARE bad text; BEGIN
  SELECT string_agg(DISTINCT m.biz_name, ', ') INTO bad
  FROM _con m LEFT JOIN businesses b ON b.id = m.biz
  WHERE b.id IS NULL OR b.name IS DISTINCT FROM m.biz_name OR b.merged_into IS NOT NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'changed since the review: %', bad; END IF;
END $$;

-- these Formers still have no contract, and no invoice is on a contract already
DO $$ DECLARE bad text; BEGIN
  SELECT string_agg(DISTINCT m.biz_name, ', ') INTO bad FROM _con m
  WHERE EXISTS (SELECT 1 FROM contracts c WHERE c.business_id = m.biz)
     OR EXISTS (SELECT 1 FROM contracts c WHERE c.qbo_invoice_id = m.qbo_invoice_id);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'already has a contract: %', bad; END IF;
END $$;

CREATE TEMP TABLE _status_before ON COMMIT DROP AS SELECT id, status FROM v_businesses;

-- backups: every business with a deal copy or a note to add, before anything changes
INSERT INTO cc_phase0_backup (table_name, row_id, before_row, reason)
SELECT 'businesses', b.id, to_jsonb(b), 'stage11b_deals_2026_10_24' FROM businesses b
WHERE b.is_club_card OR b.is_advertiser OR b.membership_type IS NOT NULL OR b.contract_start IS NOT NULL
   OR b.contract_end IS NOT NULL OR b.contract_amount IS NOT NULL OR b.deal_terms IS NOT NULL
   OR b.invoice_number IS NOT NULL OR b.contract_currency IS NOT NULL OR b.id = 'c1ccb7a6-9479-4743-bd1b-ac1335058c49';

-- (a) past contracts
INSERT INTO contracts (business_id, organization_id, membership_type, contract_start, contract_end, contract_amount,
  contract_currency, billing_frequency, deal_terms, invoice_paid, is_current, qbo_invoice_id)
SELECT m.biz, b.organization_id, m.membership_type, m.contract_start, m.contract_end, m.contract_amount,
  'GBP', 'annual', m.deal_terms, m.invoice_paid, false, m.qbo_invoice_id
FROM _con m JOIN businesses b ON b.id = m.biz ORDER BY m.n;

INSERT INTO cc_phase0_backup (table_name, row_id, before_row, reason)
SELECT 'contracts', c.id, jsonb_build_object('stage11b', 'created'), 'stage11b_deals_2026_10_24' FROM contracts c
WHERE c.id IN (SELECT c2.id FROM contracts c2 JOIN _con m ON m.biz = c2.business_id AND m.deal_terms = c2.deal_terms);

-- (b) Adam & Potsie: Tom's note, no contract
UPDATE businesses b SET notes = coalesce(nullif(rtrim(b.notes), '') || E'\n\n', '') || 'Club Card (Tom, 23 Oct 2026): they said they would sign up and Tom made their website page, then they backed out and refused to pay. No contract recorded. Invoice 1668 (£250, 30/09/2025) is being voided in QuickBooks.'
WHERE b.id = 'c1ccb7a6-9479-4743-bd1b-ac1335058c49' AND b.name = 'ADAM & POTSIE HAIRDRESSING';

-- (c) old deal text into notes, where it isn't on a contract or in the notes already
CREATE TEMP TABLE _txt ON COMMIT DROP AS
SELECT b.id, string_agg(x.line, E'\n' ORDER BY x.o) AS block
FROM businesses b
CROSS JOIN LATERAL (VALUES (1, 'Deal terms', btrim(b.deal_terms)), (2, 'Invoice number', btrim(b.invoice_number))) AS v(o, label, val)
CROSS JOIN LATERAL (SELECT v.o, '- ' || v.label || ': ' || v.val AS line) x
WHERE coalesce(v.val, '') <> ''
  AND position(lower(v.val) IN lower(coalesce(b.notes, ''))) = 0
  AND NOT EXISTS (SELECT 1 FROM contracts c WHERE c.business_id = b.id
                  AND (lower(btrim(c.deal_terms)) = lower(v.val) OR c.qbo_invoice_id = v.val))
GROUP BY b.id;

UPDATE businesses b SET notes = coalesce(nullif(rtrim(b.notes), '') || E'\n\n', '')
  || 'From the old deal fields (Stage 11b, 24 Oct 2026):' || E'\n' || t.block
FROM _txt t WHERE b.id = t.id;

-- (d) clear the copies
UPDATE businesses b SET
  is_club_card = false, is_advertiser = false, membership_type = NULL, contract_start = NULL, contract_end = NULL,
  contract_amount = NULL, contract_currency = NULL, deal_terms = NULL, invoice_number = NULL
WHERE b.id IN (SELECT row_id FROM cc_phase0_backup WHERE reason = 'stage11b_deals_2026_10_24' AND table_name = 'businesses');

SELECT public.refresh_business_truth();

-- checks
DO $$ DECLARE changed int; left_over int; lost int; nc int; BEGIN
  SELECT count(*) INTO changed FROM v_businesses v JOIN _status_before s ON s.id = v.id WHERE v.status IS DISTINCT FROM s.status;
  SELECT count(*) INTO left_over FROM businesses b WHERE b.is_club_card OR b.is_advertiser OR b.membership_type IS NOT NULL
    OR b.contract_end IS NOT NULL OR b.contract_start IS NOT NULL OR b.contract_amount IS NOT NULL OR b.deal_terms IS NOT NULL OR b.invoice_number IS NOT NULL;
  -- the start of every note is untouched
  SELECT count(*) INTO lost FROM businesses b JOIN cc_phase0_backup k ON k.row_id = b.id AND k.reason = 'stage11b_deals_2026_10_24' AND k.table_name = 'businesses'
  WHERE left(coalesce(b.notes, ''), length(rtrim(coalesce(k.before_row->>'notes', '')))) <> rtrim(coalesce(k.before_row->>'notes', ''));
  SELECT count(*) INTO nc FROM cc_phase0_backup WHERE reason = 'stage11b_deals_2026_10_24' AND table_name = 'contracts';
  IF changed > 0 OR left_over > 0 OR lost > 0 OR nc <> 65 THEN
    RAISE EXCEPTION 'check failed: % statuses changed, % copies left, % notes altered, % contracts (expected 65)', changed, left_over, lost, nc;
  END IF;
  RAISE NOTICE 'stage 11b deals: % contracts on % businesses; % notes added; copies cleared on % businesses',
    nc, 37, (SELECT count(*) FROM _txt), (SELECT count(*) FROM cc_phase0_backup WHERE reason = 'stage11b_deals_2026_10_24' AND table_name = 'businesses');
END $$;

COMMIT;
